from typing import List
import re

def separate_paren_groups(paren_string: str) -> List[str]:
    def find_groups(s, index=0):
        open_brackets = {'(': 1, '[': 2, '<': 3, '{': 4}
        close_brackets = {')': 1, ']': 2, '>': 3, '}': 4}
        brackets = [(open_brackets[c], -1) if c in open_brackets else (0, close_brackets[c]) for c in s]
        groups = []
        current_group = []
        current_level = 0

        for i, (t, level) in enumerate(brackets):
            if level > 0:
                current_level += level
            elif level < 0:
                if current_level + level <= 0:
                    current_level += level
                else:
                    groups.append(''.join(current_group))
                    current_group = []
            current_group.append(s[index:i+1])

        if current_group:
            groups.append(''.join(current_group))

        return groups if not brackets else find_groups(s[index:i+1], index=i+1)

    return find_groups(paren_string)
```

