def parse_nested_parens(paren_string: str) -> List[int]:
    def helper(s, depth=0):
        if not s:
            return depth
        if s[0] == '(':
            return helper(s[1:], depth + 1)
        if s[0] == ')':
            if depth == 0:
                return helper(s[1:], depth)
            return max(helper(s[1:], depth - 1), depth)
        return helper(s[1:], depth)

