def fibfib(n: int) -> int:
    fib_seq: Dict[int, Tuple[int, int]] = {}

    def _fibfib(n: int) -> int:
        if n == 0 or n == 1:
            return 0
        if n == 2:
            return 1
        if n in fib_seq:
            return fib_seq[n][0]

        fib_seq[n] = _fibfib(n - 1), _fibfib(n - 2), _fibfib(n - 3)
        fib_value, _, _ = fib_seq[n]
