def is_prime(n):
    if n < 2:
        return False
    primes = [True] * (n + 1)
    p = 2
    while p <= sqrt(n):
        if primes[p]:
            for i in range(p ** 2, n + 1, p):
                primes[i] = False
        p += 1
    return primes

def is_multiply_prime(a):
    primes = is_prime(100)

    # Check if a is prime
    if primes[a]:
        return False

    # Check if a is the product of three primes
    for i in range(3, len(primes)):
        if primes[i]:
            if a in (primes[i] * primes[j] * primes[k] for j in range(i + 1, len(primes)) for k in range(j + 1, len(primes))):
