from collections import deque

def max_fill(grid, capacity):
    import math
    rows, cols = len(grid), len(grid[0])
    water_count = sum(sum(row) for row in grid)
    bucket_lowers = water_count // capacity + (water_count % capacity > 0)

    if bucket_lowers == 0:
        return 0

    bucket_used = [0] * rows
    queue = deque()
    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 1 and bucket_used[row] < capacity:
                queue.append((row, col))

    result = 0
    while queue:
        size = min(capacity, len(queue))
        for _ in range(size):
            r, c = queue.popleft()
            grid[r][c] = 0
            for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                if 0 <= r + dr < rows and 0 <= c + dc < cols and grid[r + dr][c + dc] == 1:
                    bucket_used[r + dr] += 1
                    if bucket_used[r + dr] >= capacity:
                        queue.append((r + dr, c + dc))
            result += 1

    return bucket_lowers + result
```

